    # Compact each occupied column's colored cells downward, preserving order.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    out = [[bg] * w for _ in range(h)]
    for c in range(w):
        vals = [grid[r][c] for r in range(h) if grid[r][c] != bg]
        for r, v in zip(range(h-len(vals), h), vals):
            out[r][c] = v
    return out", "exit_code": 0, "error": null}

